import{_ as a,o as t,c as n,a3 as o}from"./chunks/framework.DNWyyI0w.js";const m=JSON.parse('{"title":"Connecting Telegram","description":"","frontmatter":{},"headers":[],"relativePath":"guides/telegram.md","filePath":"guides/telegram.md"}'),r={name:"guides/telegram.md"};function s(i,e,l,d,c,h){return t(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="connecting-telegram" tabindex="-1">Connecting Telegram <a class="header-anchor" href="#connecting-telegram" aria-label="Permalink to &quot;Connecting Telegram&quot;">​</a></h1><p>Telegram is a <strong>channel</strong> — a second surface onto the same PRIME, the same runs, and the same memory. Nothing about the orchestrator changes; the channel adapter translates between Telegram&#39;s API and Saidi&#39;s chat session model.</p><h2 id="set-it-up" tabindex="-1">Set it up <a class="header-anchor" href="#set-it-up" aria-label="Permalink to &quot;Set it up&quot;">​</a></h2><ol><li>Create a bot with <a href="https://t.me/BotFather" target="_blank" rel="noreferrer">@BotFather</a> and copy the token.</li><li>Open <strong>Settings → Telegram</strong> in the Saidi UI.</li><li>Paste the token and save. The adapter connects and starts receiving updates.</li></ol><h2 id="link-your-identity" tabindex="-1">Link your identity <a class="header-anchor" href="#link-your-identity" aria-label="Permalink to &quot;Link your identity&quot;">​</a></h2><p>A Telegram account is not automatically you. The adapter keeps a <strong>channel identity</strong> record mapping a Telegram user id to a Saidi member, and an unlinked sender gets nothing.</p><p>Link from the Telegram settings page, or by sending the pairing command the bot replies with on first contact. Once linked:</p><ul><li>Your messages resolve to your member record.</li><li>Runs you start from Telegram carry your <code>createdBy</code>, so <strong>your</strong> budget, permissions, and connections govern them.</li><li>Your personal memory (<code>memory/members/&lt;userId&gt;/global.md</code>) is the one that gets injected.</li></ul><div class="warning custom-block"><p class="custom-block-title">An unlinked chat is not a logged-out chat — it is a stranger</p><p>Do not add the bot to a group and assume the group is authenticated. Identity is per-sender, and each sender must be linked.</p></div><h2 id="sessions" tabindex="-1">Sessions <a class="header-anchor" href="#sessions" aria-label="Permalink to &quot;Sessions&quot;">​</a></h2><p>Each linked chat maps to a durable chat session. The conversation persists across restarts, and the same session is what the web UI shows — start a thought in Telegram and finish it in the browser.</p><h2 id="what-works-from-telegram" tabindex="-1">What works from Telegram <a class="header-anchor" href="#what-works-from-telegram" aria-label="Permalink to &quot;What works from Telegram&quot;">​</a></h2><ul><li><strong>Chat with PRIME</strong> — the full toolbelt is available, so you can start runs, ask projects questions, and record memory from your phone.</li><li><strong>Run notices</strong> — lifecycle transitions arrive as messages: finished, failed, waiting on you. These come off the same run-notice bus that feeds the reflex engine.</li><li><strong>Runs UI</strong> — an inline keyboard for listing runs, opening one, and replying into it.</li><li><strong>Approvals</strong> — a pending approval renders with Approve/Deny buttons for that exact change.</li></ul><h2 id="formatting" tabindex="-1">Formatting <a class="header-anchor" href="#formatting" aria-label="Permalink to &quot;Formatting&quot;">​</a></h2><p>Telegram&#39;s markdown dialect is narrow and unforgiving — an unbalanced backtick breaks a whole message. The adapter normalises Saidi&#39;s output before sending: fences, inline code, links, and long messages are converted and split at safe boundaries. If a code block looks mangled in Telegram but fine in the browser, that is where to look.</p><h2 id="practical-notes" tabindex="-1">Practical notes <a class="header-anchor" href="#practical-notes" aria-label="Permalink to &quot;Practical notes&quot;">​</a></h2><ul><li><strong>Keep the token in <code>.env</code></strong>, not in a repo. It is a full bot credential.</li><li><strong>Long output belongs in the web UI.</strong> Telegram is excellent for approving, steering, and being told something finished; it is a poor place to read a diff.</li><li><strong>Files</strong> sent via <code>send_file</code> arrive as Telegram documents or photos.</li></ul><p>See also: <a href="./managing-runs">Managing Runs from Chat</a> · <a href="/docs/reference/orgs-auth-permissions">Orgs, Auth &amp; Permissions</a></p>',18)])])}const u=a(r,[["render",s]]);export{m as __pageData,u as default};
